(() => {
if (window.__nexusZendeskLoaded) return; window.__nexusZendeskLoaded = true;
const state={ticketId:"",email:"",settings:null,jobId:"",timer:0,started:0}; const send=m=>new Promise(r=>chrome.runtime.sendMessage(m,r)); const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c]));
const host=document.createElement("div");host.id="nexus-zendesk-root";document.documentElement.appendChild(host);const root=host.attachShadow({mode:"open"});
root.innerHTML=`<style>:host{all:initial}.n{position:fixed;right:12px;top:74px;width:380px;max-height:calc(100vh - 92px);z-index:2147483000;background:#0d1425;color:#edf2ff;border:1px solid #2b3857;border-radius:12px;box-shadow:0 18px 50px #0007;font:13px/1.45 Arial,sans-serif;overflow:hidden}.h{display:flex;align-items:center;justify-content:space-between;padding:12px 14px;background:#121c32;border-bottom:1px solid #26334f}.brand{font-weight:800}.sub{font-size:11px;opacity:.65}.b{background:#192641;color:white;border:1px solid #31405f;border-radius:7px;padding:6px 9px;cursor:pointer}.body{padding:12px;overflow:auto;max-height:calc(100vh - 150px)}.card{background:#111a2e;border:1px solid #283653;border-radius:10px;padding:11px;margin-bottom:10px}.bar{height:8px;background:#202d49;border-radius:99px;overflow:hidden}.fill{height:100%;background:#6ea8fe;width:0;transition:width .25s}.row{display:flex;justify-content:space-between;gap:8px}.bad{background:#3a1820}.muted{opacity:.7}.hide .body{display:none}.hide{width:230px}.tabs{display:flex;gap:6px;margin-bottom:10px}.tabs button{flex:1}.pre{white-space:pre-wrap;word-break:break-word}.small{font-size:11px}.dot{display:inline-block;width:8px;height:8px;border-radius:50%;background:#55d68b;margin-right:6px}</style><section class="n"><div class="h"><div><div class="brand"><span class="dot"></span>Nexus Copilot</div><div class="sub" id="status">Starting…</div></div><div><button class="b" id="analyze">Analyze</button> <button class="b" id="collapse">—</button></div></div><div class="body"><div class="card"><div class="row"><span id="stage">Ready</span><b id="pct">0%</b></div><div class="bar"><div class="fill" id="fill"></div></div><div class="row small muted"><span id="timer">00:00</span><span id="queue"></span></div></div><div class="tabs"><button class="b" data-tab="result">Recommendation</button><button class="b" data-tab="ticket">Ticket</button><button class="b" data-tab="privacy">Data</button></div><div id="content" class="card">Open a Zendesk ticket.</div></div></section>`;
const q=s=>root.querySelector(s),panel=q(".n"); function fmt(sec){sec=Math.max(0,Math.floor(sec));return `${String(Math.floor(sec/60)).padStart(2,"0")}:${String(sec%60).padStart(2,"0")}`;} function progress(p,stage,queue=""){q("#fill").style.width=`${Math.max(0,Math.min(100,p))}%`;q("#pct").textContent=`${Math.round(p)}%`;q("#stage").textContent=stage;q("#queue").textContent=queue;} function startTimer(){clearInterval(state.timer);state.started=Date.now();q("#timer").textContent="00:00";state.timer=setInterval(()=>q("#timer").textContent=fmt((Date.now()-state.started)/1000),250);} function stopTimer(){clearInterval(state.timer);} function ticketId(){return location.pathname.match(/\/agent\/tickets\/(\d+)/)?.[1]||"";} async function getJson(url){const r=await fetch(url,{credentials:"include"});if(!r.ok)throw new Error(`${r.status} ${url}`);return r.json();} function cleanText(v){return String(v??"").replace(/\b(?:axios|httpx|user-agent|ip address|analytics|tracking)\b[^\n]*/gi,"").replace(/https?:\/\/\S+/g,"[url removed]").trim();}
async function readTicket(){const id=ticketId();if(!id)throw new Error("No Zendesk ticket open");progress(8,"Reading Zendesk ticket");const [t,c,me,fields]=await Promise.all([getJson(`/api/v2/tickets/${id}.json`),getJson(`/api/v2/tickets/${id}/comments.json?sort_order=asc`),getJson(`/api/v2/users/me.json`),getJson(`/api/v2/ticket_fields.json`).catch(()=>({ticket_fields:[]}))]);state.email=me.user?.email||"";const fieldMap=new Map((fields.ticket_fields||[]).map(f=>[String(f.id),f.title]));const custom=(t.ticket.custom_fields||[]).map(f=>`${fieldMap.get(String(f.id))||f.id}: ${f.value??""}`).join("\n");let payload={ticket_id:String(id),subject:cleanText(t.ticket.subject),requester:String(t.ticket.requester_id||""),status:t.ticket.status||"",priority:t.ticket.priority||"",brand:String(t.ticket.brand_id||""),group:String(t.ticket.group_id||""),assignee:String(t.ticket.assignee_id||""),tags:t.ticket.tags||[],public_comments:(c.comments||[]).filter(x=>x.public).map(x=>cleanText(x.plain_body||x.body)).filter(Boolean).slice(-20),internal_comments:(c.comments||[]).filter(x=>!x.public).map(x=>cleanText(x.plain_body||x.body)).filter(Boolean).slice(-20),reservation_context:cleanText(custom),instruction:"Analyze this Zendesk ticket and recommend the next best action according to the official Ticket Matrix and approved policy."};const s=state.settings||{};if(s.stripEmail){payload.public_comments=payload.public_comments.map(x=>x.replace(/[\w.+-]+@[\w.-]+\.[A-Za-z]{2,}/g,"[email removed]"));payload.internal_comments=payload.internal_comments.map(x=>x.replace(/[\w.+-]+@[\w.-]+\.[A-Za-z]{2,}/g,"[email removed]"));}if(s.stripPhone){for(const k of ["public_comments","internal_comments"])payload[k]=payload[k].map(x=>x.replace(/\+?\d[\d\s().-]{7,}\d/g,"[phone removed]"));}return payload;}
async function analyze(){try{startTimer();progress(2,"Preparing analysis");const payload=await readTicket();state.lastPayload=payload;state.dataHtml=`<div class="small muted">Exactly what will be sent to Nexus:</div><pre class="pre small">${esc(JSON.stringify(payload,null,2))}</pre>`;progress(18,"Sanitizing and joining queue");const sub=await send({type:"backend",method:"POST",path:"/api/extension/analyze",email:state.email,body:payload});if(!sub.ok)throw new Error(sub.data?.error||sub.error||`Server ${sub.status}`);state.jobId=sub.data.job_id;let done=null;while(!done){const pol=await send({type:"backend",path:`/api/extension/jobs/${encodeURIComponent(state.jobId)}`,email:state.email});if(!pol.ok)throw new Error(pol.data?.error||"Queue status error");const j=pol.data;if(j.status==="queued"){const p=Math.min(35,20+Math.max(0,15-j.position));progress(p,`Waiting for Nexus — position ${j.position}`,`waited ${fmt(j.waited_seconds)} · est ${fmt(j.estimated_wait_seconds)}`);}else if(j.status==="running"){const p=Math.min(90,40+(j.running_seconds/Math.max(1,j.average_job_seconds))*45);progress(p,"Nexus is analyzing",`${fmt(j.running_seconds)} elapsed · ~${fmt(j.estimated_wait_seconds)} left`);}else if(j.status==="done")done=j.result;else if(j.status==="error")throw new Error(j.error||"Nexus failed");if(!done)await new Promise(r=>setTimeout(r,1000));}progress(96,"Preparing recommendation");const answer=done?.answer||"No answer returned";q("#content").innerHTML=`<div class="pre">${esc(answer)}</div><hr style="border-color:#29334d"><div class="small muted">Verified: ${esc(done?.verified??false)} · Model: ${esc(done?.model||"")}</div>`;progress(100,"Complete");q("#status").textContent=`Ticket ${payload.ticket_id} · ${state.email}`;stopTimer();}catch(e){stopTimer();progress(0,"Unable to analyze");q("#content").innerHTML=`<div class="bad"><b>Nexus unavailable</b><div class="small">${esc(e instanceof Error?e.message:e)}</div></div>`;}}
async function boot(){const s=await send({type:"settings:get"});state.settings=s.settings||{};state.ticketId=ticketId();q("#status").textContent=state.ticketId?`Ticket ${state.ticketId}`:"No ticket open";if(state.ticketId&&state.settings.autoAnalyze)void analyze();}q("#analyze").addEventListener("click",analyze);q("#collapse").addEventListener("click",()=>panel.classList.toggle("hide"));root.querySelectorAll("[data-tab]").forEach(el=>el.addEventListener("click",async()=>{const tab=el.dataset.tab;if(tab==="ticket"){try{q("#content").innerHTML=`<pre class="pre small">${esc(JSON.stringify(await readTicket(),null,2))}</pre>`;}catch{}}else if(tab==="privacy")q("#content").innerHTML=state.dataHtml||"Analyze a ticket first.";}));let deb;const changed=()=>{clearTimeout(deb);deb=setTimeout(()=>{const id=ticketId();if(id!==state.ticketId){state.ticketId=id;q("#status").textContent=id?`Ticket ${id}`:"No ticket open";if(id&&state.settings?.autoAnalyze)void analyze();}},Number(state.settings?.debounceMs||1500));};new MutationObserver(changed).observe(document.body,{subtree:true,childList:true});window.addEventListener("popstate",changed);setInterval(changed,1500);void boot();
})();
